INSERT INTO merit_formulas (university_id, formula_name, matric_weight, intermediate_weight, entry_test_weight, formula_details, updated_by) VALUES
(133, 'BS Computer Science / SE / BBA / General UG | Engineering programs', 10, 50, 40, '{"university":"Abasyn University","abbreviation":"ABASYN","programGroup":"BS Computer Science / SE / BBA / General UG | Engineering programs","formula":{"text":"10% Matric + 50% Intermediate + 40% Entry Test.","matric":10,"intermediate":50,"entryTest":40,"interview":0,"total":100},"testInfo":{"acceptedTests":"Abasyn internal test / NTS NAT / ETEA | ETEA / internal test","eligibility":"CS 50%; other thresholds by program. | 60% FSc Pre-Engineering.","hafizRule":"No explicit Hafiz policy found online; verify."},"priority":"P1 - Top priority","notes":""}', 1),
(55, 'BS CS / Software Engineering / Biomedical Engineering / Science & Tech | Pharm-D / DPT', 0, 50, 50, '{"university":"Ziauddin University","abbreviation":"ZU","programGroup":"BS CS / Software Engineering / Biomedical Engineering / Science & Tech | Pharm-D / DPT","formula":{"text":"(Inter% * 0.50) + (ZU_Entry_Test% * 0.50)","matric":0,"intermediate":50,"entryTest":50,"interview":0,"total":100},"testInfo":{"acceptedTests":"Ziauddin University Entry Test","eligibility":"BS CS/SE 50% Inter; Biomedical Engineering 60% FSc Pre-Eng/Pre-Med | 60% FSc Pre-Medical","hafizRule":"Not specified"},"priority":"P1 - Top priority","notes":""}', 1),
(55, 'MBBS / BDS', 10, 40, 50, '{"university":"Ziauddin University","abbreviation":"ZU","programGroup":"MBBS / BDS","formula":{"text":"(Matric% * 0.10) + (FSc% * 0.40) + (MDCAT% * 0.50)","matric":10,"intermediate":40,"entryTest":50,"interview":0,"total":100},"testInfo":{"acceptedTests":"MDCAT via JSMU/PMDC/Dow as applicable","eligibility":"MBBS 60% FSc + 55% MDCAT; BDS 50% FSc + 50% MDCAT","hafizRule":"Not specified"},"priority":"P1 - Top priority","notes":""}', 1),
(213, 'All Non-Engineering BS', 30, 70, 0, '{"university":"University of Chakwal","abbreviation":"UOC","programGroup":"All Non-Engineering BS","formula":{"text":"30% Matric + 70% FSc","matric":30,"intermediate":70,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"Not specified","eligibility":"Intermediate min 45% general or 50% CS/IT","hafizRule":"Not specified"},"priority":"P1 - Top priority","notes":""}', 1),
(213, 'LLB 5-Year', 30, 70, 0, '{"university":"University of Chakwal","abbreviation":"UOC","programGroup":"LLB 5-Year","formula":{"text":"30% Matric + 70% FSc; LAT qualifying","matric":30,"intermediate":70,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"HEC LAT qualifying","eligibility":"Intermediate min 45% + LAT 50","hafizRule":"Not specified"},"priority":"P1 - Top priority","notes":""}', 1),
(213, 'Pharm-D', 30, 70, 0, '{"university":"University of Chakwal","abbreviation":"UOC","programGroup":"Pharm-D","formula":{"text":"30% Matric + 70% FSc (test if conducted qualifying)","matric":30,"intermediate":70,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"Departmental Test if conducted","eligibility":"FSc Pre-Medical min 60%","hafizRule":"Not specified"},"priority":"P1 - Top priority","notes":""}', 1),
(16, 'Bachelor programs CPN', 10, 30, 60, '{"university":"University of Sindh","abbreviation":"UOS / USindh","programGroup":"Bachelor programs CPN","formula":{"text":"CPN = Matric 10% + Intermediate 30% + Pre-Entry Test score 60%.","matric":10,"intermediate":30,"entryTest":60,"interview":0,"total":100},"testInfo":{"acceptedTests":"University of Sindh Pre-Entry Test","eligibility":"Check university website","hafizRule":"Not specified"},"priority":"P1 - Top priority","notes":""}', 1),
(16, 'LLB Hons', 10, 30, 60, '{"university":"University of Sindh","abbreviation":"UOS / USindh","programGroup":"LLB Hons","formula":{"text":"CPN = Matric 10% + Intermediate 30% + Test score 60%. For law, LAT is used/required as the law admission test according to law-admission rules.","matric":10,"intermediate":30,"entryTest":60,"interview":0,"total":100},"testInfo":{"acceptedTests":"HEC LAT / applicable test per Sindh University law admission portal","eligibility":"LAT 50/100 minimum is commonly required by HEC law admission rules; confirm annually.","hafizRule":"Not specified"},"priority":"P1 - Top priority","notes":""}', 1),
(135, 'General BS / CS / SE / BBA', 0, 0, 0, '{"university":"Islamia College Peshawar","abbreviation":"ICP","programGroup":"General BS / CS / SE / BBA","formula":{"text":"Intermediate_obtained_marks + (Matric_obtained_marks * 0.10)","matric":0,"intermediate":0,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"Not specified","eligibility":"CS/SE 50% Inter; General BS 45% Inter","hafizRule":"Not specified"},"priority":"P2 - High priority","notes":""}', 1),
(135, 'LLB 5 Years', 0, 0, 0, '{"university":"Islamia College Peshawar","abbreviation":"ICP","programGroup":"LLB 5 Years","formula":{"text":"Intermediate_obtained_marks + (Matric_obtained_marks * 0.10); LAT qualifying only","matric":0,"intermediate":0,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"HEC LAT","eligibility":"45% Inter + 50% LAT","hafizRule":"Not specified"},"priority":"P2 - High priority","notes":""}', 1),
(104, 'Computing | General BS', 10, 40, 50, '{"university":"Mirpur University of Science and Technology","abbreviation":"MUST","programGroup":"Computing | General BS","formula":{"text":"(Matric % * 0.10) + (FSc % * 0.40) + (Entry Test % * 0.50)","matric":10,"intermediate":40,"entryTest":50,"interview":0,"total":100},"testInfo":{"acceptedTests":"MUST Entry Test | MUST Entry Test / Departmental Test","eligibility":"Min 50% in FSc Pre-Engineering / ICS / Pre-Medical; pre-medical students need math deficiency courses | Min 45% in Intermediate","hafizRule":"+20 marks added to Intermediate obtained marks before percentage calculation."},"priority":"P2 - High priority","notes":""}', 1),
(104, 'Engineering', 10, 40, 50, '{"university":"Mirpur University of Science and Technology","abbreviation":"MUST","programGroup":"Engineering","formula":{"text":"(Matric % * 0.10) + (FSc/DAE % * 0.40) + (Entry Test % * 0.50)","matric":10,"intermediate":40,"entryTest":50,"interview":0,"total":100},"testInfo":{"acceptedTests":"MUST Entry Test (SEET) or ETEA if permitted","eligibility":"Min 60% in FSc Pre-Engineering / DAE","hafizRule":"+20 marks added to Intermediate/DAE obtained marks before percentage calculation."},"priority":"P2 - High priority","notes":""}', 1),
(183, 'All BS Programs', 20, 50, 30, '{"university":"University of Swabi","abbreviation":"UOSwabi","programGroup":"All BS Programs","formula":{"text":"50% FSc + 20% Matric + 30% Test","matric":20,"intermediate":50,"entryTest":30,"interview":0,"total":100},"testInfo":{"acceptedTests":"HEC USAT / Internal Test","eligibility":"Intermediate min 45% general or 50% science/CS","hafizRule":"Not specified"},"priority":"P2 - High priority","notes":""}', 1),
(183, 'LLB 5-Year', 20, 50, 30, '{"university":"University of Swabi","abbreviation":"UOSwabi","programGroup":"LLB 5-Year","formula":{"text":"50% FSc + 20% Matric + 30% LAT","matric":20,"intermediate":50,"entryTest":30,"interview":0,"total":100},"testInfo":{"acceptedTests":"HEC LAT","eligibility":"Intermediate min 45% + LAT 50","hafizRule":"Not specified"},"priority":"P2 - High priority","notes":""}', 1),
(112, 'Education', 0, 0, 40, '{"university":"Gomal University","abbreviation":"GU / Gomal","programGroup":"Education","formula":{"text":"(Academic Score * 0.60) + (Test % * 0.40), where Academic Score = ((Matric % * 1) + (FSc % * 2)) / 3","matric":0,"intermediate":0,"entryTest":40,"interview":0,"total":40},"testInfo":{"acceptedTests":"NTS / Departmental Test","eligibility":"Min 45% in FA/FSc","hafizRule":"+20 marks added to FSc/HSSC obtained marks before calculating adjusted FSc percentage."},"priority":"P2 - High priority","notes":""}', 1),
(112, 'General BS Programs', 33.3, 66.7, 0, '{"university":"Gomal University","abbreviation":"GU / Gomal","programGroup":"General BS Programs","formula":{"text":"((Matric % * 1) + (FSc % * 2)) / 3","matric":33.3,"intermediate":66.7,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"None; merit based on academics","eligibility":"Min 45% in Intermediate","hafizRule":"+20 marks added to FSc/HSSC obtained marks before calculating adjusted FSc percentage."},"priority":"P2 - High priority","notes":""}', 1),
(112, 'Pharm-D', 0, 0, 40, '{"university":"Gomal University","abbreviation":"GU / Gomal","programGroup":"Pharm-D","formula":{"text":"(Academic Score * 0.60) + (Entry Test % * 0.40), where Academic Score = ((Matric % * 1) + (FSc % * 2)) / 3","matric":0,"intermediate":0,"entryTest":40,"interview":0,"total":40},"testInfo":{"acceptedTests":"Gomal University Pharmacy Test","eligibility":"Min 60% in FSc Pre-Medical","hafizRule":"+20 marks added to FSc/HSSC obtained marks before calculating adjusted FSc percentage."},"priority":"P2 - High priority","notes":""}', 1),
(84, 'MBBS / BDS', 10, 40, 50, '{"university":"Isra University","abbreviation":"ISRA","programGroup":"MBBS / BDS","formula":{"text":"10% Matric + 40% FSc + 50% MDCAT.","matric":10,"intermediate":40,"entryTest":50,"interview":0,"total":100},"testInfo":{"acceptedTests":"MDCAT / Provincial centralized test","eligibility":"60% FSc Pre-Medical.","hafizRule":"+20 marks added to FSc obtained only if Hafiz test passed, per AI Mode chat."},"priority":"P2 - High priority","notes":""}', 1),
(117, 'BS General / CS / SE / IT / Sciences / Arts', 0, 100, 0, '{"university":"University of Swat","abbreviation":"USWAT","programGroup":"BS General / CS / SE / IT / Sciences / Arts","formula":{"text":"Merit % = Intermediate / HSSC / equivalent qualifying examination percentage","matric":0,"intermediate":100,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"None / No standard entry test","eligibility":"Minimum eligibility generally at least 45% marks or 2nd division in FA/FSc or equivalent; computing programs require relevant eligibility such as FSc/ICS/FA with Mathematics or equivalent with 50% marks where stated.","hafizRule":"Not found in fetched official source"},"priority":"P2 - High priority","notes":""}', 1),
(117, 'BS Programs if entry test is held', 0, 0, 0, '{"university":"University of Swat","abbreviation":"USWAT","programGroup":"BS Programs if entry test is held","formula":{"text":"No verified official formula found for 90% Intermediate + 10% Entry Test.","matric":0,"intermediate":0,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"USWAT entry test if officially announced","eligibility":"Use only if University of Swat publishes a current program-specific entry-test weightage formula.","hafizRule":"Not found in fetched official source"},"priority":"P2 - High priority","notes":""}', 1),
(117, 'LLB 5-Year / Law and Shariah', 0, 100, 0, '{"university":"University of Swat","abbreviation":"USWAT","programGroup":"LLB 5-Year / Law and Shariah","formula":{"text":"Merit % = Intermediate / HSSC / equivalent qualifying examination percentage; HEC LAT is mandatory qualifying requirement only","matric":0,"intermediate":100,"entryTest":0,"interview":0,"total":100},"testInfo":{"acceptedTests":"HEC LAT qualifying","eligibility":"Minimum eligibility generally FA/FSc or equivalent; candidate must pass Law Admission Test conducted by HEC before admission.","hafizRule":"Not found in fetched official source"},"priority":"P2 - High priority","notes":""}', 1),
